import java.util.Scanner;

public class Main {
    static final int MAXN = 510;
    static int N, M, MOD;
    static int[][] C = new int[MAXN][MAXN];
    static Pair[][] DP = new Pair[MAXN][MAXN];

    static class Pair {
        int first;
        int second;

        Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }

        Pair add(Pair b) {
            return new Pair(addMod(this.first, b.first), addMod(this.second, b.second));
        }

        Pair multiply(Pair b) {
            long fiPart = ((long) this.first * b.first) % MOD;
            long sePart = ((long) this.first * b.second + (long) this.second * b.first) % MOD;
            return new Pair((int) fiPart, (int) sePart);
        }
    }

    static int sumRange(int l, int r) {
        return (l + r) * (r - l + 1) / 2;
    }

    static int addMod(int a, int b) {
        int res = a + b;
        if (res >= MOD) res -= MOD;
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        MOD = sc.nextInt();

        for (int i = 0; i < MAXN; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = addMod(C[i - 1][j], C[i - 1][j - 1]);
            }
        }

        for (int i = 0; i <= N; i++) {
            for (int j = 0; j <= M; j++) {
                DP[i][j] = new Pair(0, 0);
            }
        }

        for (int i = 0; i <= N; i++) {
            DP[i][0] = new Pair(1, 0);
            for (int j = 1; j <= i && j <= M; j++) {
                if (i != j) {
                    for (int k = 1; k <= i; k++) {
                        Pair temp = DP[k - 1][k - 1].multiply(DP[i - k][j - k + 1]).multiply(new Pair(C[j][k - 1], 0));
                        DP[i][j] = DP[i][j].add(temp);
                    }
                } else {
                    for (int k = 1; k <= i; k++) {
                        Pair t1 = DP[k - 1][k - 1];
                        Pair t2 = DP[i - k][i - k];
                        Pair comb = new Pair(C[i - 1][k - 1], 0);
                        int fct = i + 1 - sumRange(1, k) + sumRange(k + 1, i) - k * (i - k);
                        Pair fctPair = new Pair(fct, 0);
                        Pair temp = t1.multiply(t2).multiply(comb).multiply(fctPair);
                        DP[i][j] = DP[i][j].add(temp);
                    }
                }
            }
        }

        System.out.println(DP[N][M].second);
        sc.close();
    }
}
